package com.booksyde.controller; import com.booksyde.dto.request.CheckoutRequest; import com.booksyde.dto.response.CheckoutResponse; import com.booksyde.service.PaymentService; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/payments") public class PaymentController{private final PaymentService service;public PaymentController(PaymentService s){service=s;}@PostMapping("/checkout")public CheckoutResponse checkout(@Valid @RequestBody CheckoutRequest r,@org.springframework.security.core.annotation.AuthenticationPrincipal Jwt jwt){return service.checkout(r.orderId(),UUID.fromString(jwt.getSubject()));}}
